-- ============================================================================
-- BAUST: Confirm Pending Unverified Users in Supabase Auth
-- Run in Supabase Dashboard -> SQL Editor if users receive:
--   "Email not confirmed" / "Your email address has not been confirmed yet"
-- Note: Only updates email_confirmed_at (confirmed_at is generated by Supabase Auth).
-- ============================================================================

UPDATE auth.users
SET email_confirmed_at = COALESCE(email_confirmed_at, NOW())
WHERE email_confirmed_at IS NULL
  AND COALESCE(is_anonymous, FALSE) = FALSE;
